{
  "name": "FonoFlow - Gestão de Clínica Fonoaudiológica",
  "description": "Sistema completo para gerenciamento de clínicas de fonoaudiologia, cobrindo desde o cadastro de pacientes até o fluxo financeiro e pós-atendimento.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum UserRole {
  ADMIN = 'ADMIN',
  GERENTE = 'GERENTE',
  ATENDENTE = 'ATENDENTE',
  PACIENTE = 'PACIENTE'
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  password?: string;
}

export interface Patient {
  id: string;
  fullName: string;
  birthDate: string;
  age: number;
  phone: string;
  email: string;
}

export enum AppointmentStatus {
  A_CONFIRMAR = 'A Confirmar',
  CONFIRMADO = 'Confirmado',
  FALTOU = 'Faltou',
  DESMARCADO = 'Desmarcado'
}

export interface Appointment {
  id: string;
  patientId: string;
  date: string;
  time: string;
  location: string;
  status: AppointmentStatus;
}

export enum TriageStatus {
  PASSA = 'Passa',
  ENCAMINHA = 'Encaminha',
  FALHA = 'Falha'
}

export interface Triage {
  id: string;
  appointmentId: string;
  date: string;
  time: string;
  location: string;
  status: TriageStatus;
}

export enum RecordType {
  CONSULTA_AVALIACAO = 'Consulta/Avaliação',
  RETORNO = 'Retorno',
  EXAME = 'Exame',
  SESSAO = 'Sessão'
}

export interface MedicalRecord {
  id: string;
  appointmentId: string;
  type: RecordType;
  details: any;
  createdAt: string;
}

export enum PaymentMethod {
  DINHEIRO = 'Dinheiro',
  PIX = 'PIX',
  TRANSFERENCIA = 'Transferência',
  DEBITO = 'Débito',
  CREDITO = 'Crédito',
  BOLETO = 'Boleto',
  OUTRO = 'Outro'
}

export interface Transaction {
  id: string;
  appointmentId: string;
  patientId: string;
  type: 'PAGAR' | 'RECEBER' | 'RECEBIDO';
  description: string;
  value: number;
  method?: PaymentMethod;
  date: string;
}

export interface AppState {
  users: User[];
  patients: Patient[];
  appointments: Appointment[];
  triages: Triage[];
  records: MedicalRecord[];
  transactions: Transaction[];
  currentUser: User | null;
}

export const calculateAge = (birthDate: string): number => {
  const today = new Date();
  const birth = new Date(birthDate);
  let age = today.getFullYear() - birth.getFullYear();
  const m = today.getMonth() - birth.getMonth();
  if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) {
    age--;
  }
  return age;
};

export const formatCurrency = (value: number): string => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value);
};

export const formatDate = (date: string): string => {
  return new Date(date).toLocaleDateString('pt-BR');
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, Patient, Appointment, Triage, MedicalRecord, Transaction, UserRole, AppState, AppointmentStatus } from '../types';

interface AppContextType extends AppState {
  login: (email: string, role: UserRole) => void;
  logout: () => void;
  addPatient: (p: Omit<Patient, 'id' | 'age'>) => void;
  addAppointment: (a: Omit<Appointment, 'id'>) => void;
  updateAppointmentStatus: (id: string, status: AppointmentStatus) => void;
  addTriage: (t: Omit<Triage, 'id'>) => void;
  addMedicalRecord: (r: Omit<MedicalRecord, 'id' | 'createdAt'>) => void;
  addTransaction: (t: Omit<Transaction, 'id'>) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

import { calculateAge } from '../utils/helpers';

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('fonoflow_data');
    if (saved) return JSON.parse(saved);
    return {
      users: [
        { id: '1', name: 'Admin Flow', email: 'admin@fono.com', role: UserRole.ADMIN },
        { id: '2', name: 'Gerente Ana', email: 'gerente@fono.com', role: UserRole.GERENTE },
        { id: '3', name: 'Atendente Bia', email: 'atendente@fono.com', role: UserRole.ATENDENTE },
      ],
      patients: [],
      appointments: [],
      triages: [],
      records: [],
      transactions: [],
      currentUser: null,
    };
  });

  useEffect(() => {
    localStorage.setItem('fonoflow_data', JSON.stringify(state));
  }, [state]);

  const login = (email: string, role: UserRole) => {
    const user = state.users.find(u => u.email === email && u.role === role) || {
      id: Math.random().toString(),
      name: email.split('@')[0],
      email,
      role
    };
    setState(prev => ({ ...prev, currentUser: user }));
  };

  const logout = () => setState(prev => ({ ...prev, currentUser: null }));

  const addPatient = (p: Omit<Patient, 'id' | 'age'>) => {
    const newPatient: Patient = {
      ...p,
      id: Math.random().toString(36).substr(2, 9),
      age: calculateAge(p.birthDate)
    };
    setState(prev => ({ ...prev, patients: [...prev.patients, newPatient] }));
  };

  const addAppointment = (a: Omit<Appointment, 'id'>) => {
    const newApp: Appointment = { ...a, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, appointments: [...prev.appointments, newApp] }));
  };

  const updateAppointmentStatus = (id: string, status: AppointmentStatus) => {
    setState(prev => ({
      ...prev,
      appointments: prev.appointments.map(a => a.id === id ? { ...a, status } : a)
    }));
  };

  const addTriage = (t: Omit<Triage, 'id'>) => {
    const newTriage: Triage = { ...t, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, triages: [...prev.triages, newTriage] }));
  };

  const addMedicalRecord = (r: Omit<MedicalRecord, 'id' | 'createdAt'>) => {
    const newRecord: MedicalRecord = { 
      ...r, 
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    };
    setState(prev => ({ ...prev, records: [...prev.records, newRecord] }));
  };

  const addTransaction = (t: Omit<Transaction, 'id'>) => {
    const newTrans: Transaction = { ...t, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, transactions: [...prev.transactions, newTrans] }));
  };

  return (
    <AppContext.Provider value={{ 
      ...state, 
      login, 
      logout, 
      addPatient, 
      addAppointment, 
      updateAppointmentStatus,
      addTriage,
      addMedicalRecord,
      addTransaction
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within AppProvider');
  return context;
};

import React from 'react';
import { useApp } from '../store/AppContext';
import { UserRole } from '../types';
import { 
  LayoutDashboard, 
  Users, 
  Calendar, 
  Stethoscope, 
  FileText, 
  CreditCard, 
  BarChart3, 
  MessageSquare, 
  LogOut,
  Menu,
  X
} from 'lucide-react';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab }) => {
  const { currentUser, logout } = useApp();
  const [isSidebarOpen, setIsSidebarOpen] = React.useState(true);

  if (!currentUser) return <>{children}</>;

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, roles: [UserRole.ADMIN, UserRole.GERENTE, UserRole.ATENDENTE, UserRole.PACIENTE] },
    { id: 'patients', label: 'Pacientes', icon: Users, roles: [UserRole.ADMIN, UserRole.GERENTE, UserRole.ATENDENTE] },
    { id: 'agenda', label: 'Agenda', icon: Calendar, roles: [UserRole.ADMIN, UserRole.GERENTE, UserRole.ATENDENTE, UserRole.PACIENTE] },
    { id: 'triage', label: 'Triagem', icon: Stethoscope, roles: [UserRole.ADMIN, UserRole.GERENTE, UserRole.ATENDENTE] },
    { id: 'records', label: 'Prontuários', icon: FileText, roles: [UserRole.ADMIN, UserRole.GERENTE, UserRole.ATENDENTE] },
    { id: 'finance', label: 'Financeiro', icon: CreditCard, roles: [UserRole.ADMIN, UserRole.GERENTE] },
    { id: 'reports', label: 'Relatórios', icon: BarChart3, roles: [UserRole.ADMIN, UserRole.GERENTE] },
    { id: 'postcare', label: 'Pós-Atendimento', icon: MessageSquare, roles: [UserRole.ADMIN, UserRole.ATENDENTE] },
  ];

  const filteredItems = menuItems.filter(item => item.roles.includes(currentUser.role));

  return (
    <div className="min-h-screen flex text-slate-800">
      {/* Sidebar */}
      <aside className={`bg-white border-r border-slate-200 transition-all duration-300 ${isSidebarOpen ? 'w-64' : 'w-20'} flex flex-col fixed h-full z-50`}>
        <div className="p-6 flex items-center justify-between border-b border-slate-100">
          <span className={`font-bold text-indigo-600 text-xl truncate ${!isSidebarOpen && 'hidden'}`}>FonoFlow</span>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-1 hover:bg-slate-100 rounded">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        <nav className="flex-1 mt-6 px-3 space-y-2">
          {filteredItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center px-4 py-3 rounded-lg transition-colors ${
                activeTab === item.id 
                ? 'bg-indigo-50 text-indigo-700' 
                : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
              }`}
            >
              <item.icon size={20} />
              <span className={`ml-3 font-medium ${!isSidebarOpen && 'hidden'}`}>{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100">
          <div className={`mb-4 flex items-center ${!isSidebarOpen && 'justify-center'}`}>
            <div className="w-8 h-8 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center font-bold">
              {currentUser.name[0]}
            </div>
            {isSidebarOpen && (
              <div className="ml-3 overflow-hidden">
                <p className="text-sm font-semibold truncate">{currentUser.name}</p>
                <p className="text-xs text-slate-400 truncate uppercase">{currentUser.role}</p>
              </div>
            )}
          </div>
          <button 
            onClick={logout}
            className={`w-full flex items-center px-4 py-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors ${!isSidebarOpen && 'justify-center'}`}
          >
            <LogOut size={20} />
            <span className={`ml-3 font-medium ${!isSidebarOpen && 'hidden'}`}>Sair</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className={`flex-1 flex flex-col transition-all duration-300 ${isSidebarOpen ? 'ml-64' : 'ml-20'}`}>
        <header className="h-16 bg-white border-b border-slate-200 flex items-center px-8 sticky top-0 z-40">
          <h1 className="text-xl font-bold text-slate-800">
            {menuItems.find(i => i.id === activeTab)?.label}
          </h1>
          <div className="ml-auto flex items-center gap-4">
             <span className="text-sm text-slate-500">{new Date().toLocaleDateString('pt-BR', { dateStyle: 'long' })}</span>
          </div>
        </header>

        <div className="p-8 max-w-7xl mx-auto w-full">
          {children}
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React from 'react';
import { useApp } from '../store/AppContext';
import { UserRole, AppointmentStatus } from '../types';
import { Calendar, Users, TrendingUp, AlertCircle } from 'lucide-react';
import { formatCurrency, formatDate } from '../utils/helpers';

const Dashboard: React.FC = () => {
  const { patients, appointments, currentUser, updateAppointmentStatus } = useApp();

  const todayStr = new Date().toISOString().split('T')[0];
  const todayAppointments = appointments.filter(a => a.date === todayStr);
  const pendingAppointments = appointments.filter(a => a.status === AppointmentStatus.A_CONFIRMAR);

  const stats = [
    { label: 'Hoje', value: todayAppointments.length, icon: Calendar, color: 'bg-blue-500' },
    { label: 'Total Pacientes', value: patients.length, icon: Users, color: 'bg-indigo-500' },
    { label: 'Pendentes', value: pendingAppointments.length, icon: AlertCircle, color: 'bg-amber-500' },
    { label: 'Mensal', value: formatCurrency(25000), icon: TrendingUp, color: 'bg-emerald-500' },
  ];

  if (currentUser?.role === UserRole.PACIENTE) {
    const myPatient = patients.find(p => p.email === currentUser.email);
    const myAppointments = appointments.filter(a => a.patientId === myPatient?.id);

    return (
      <div className="space-y-6">
        <h2 className="text-2xl font-bold">Olá, {currentUser.name}!</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <h3 className="font-bold text-lg mb-4">Meus Agendamentos</h3>
            <div className="space-y-4">
              {myAppointments.length > 0 ? myAppointments.map(app => (
                <div key={app.id} className="p-4 border border-slate-100 rounded-lg flex items-center justify-between">
                  <div>
                    <p className="font-semibold">{formatDate(app.date)} às {app.time}</p>
                    <p className="text-sm text-slate-500">{app.location}</p>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                    app.status === AppointmentStatus.CONFIRMADO ? 'bg-green-100 text-green-700' : 
                    app.status === AppointmentStatus.A_CONFIRMAR ? 'bg-amber-100 text-amber-700' : 'bg-red-100 text-red-700'
                  }`}>
                    {app.status}
                  </span>
                </div>
              )) : <p className="text-slate-500 italic">Nenhum agendamento encontrado.</p>}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center">
            <div className={`${stat.color} p-3 rounded-xl text-white mr-4`}>
              <stat.icon size={24} />
            </div>
            <div>
              <p className="text-sm text-slate-500 font-medium">{stat.label}</p>
              <p className="text-2xl font-bold">{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Today's Agenda */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center">
            <h3 className="font-bold text-lg">Agenda de Hoje</h3>
            <span className="text-xs font-bold bg-indigo-50 text-indigo-600 px-2 py-1 rounded">{todayAppointments.length}</span>
          </div>
          <div className="divide-y divide-slate-100 max-h-[400px] overflow-y-auto">
            {todayAppointments.length > 0 ? todayAppointments.map(app => {
              const patient = patients.find(p => p.id === app.patientId);
              return (
                <div key={app.id} className="p-4 hover:bg-slate-50 transition-colors flex items-center justify-between">
                  <div className="flex items-center">
                    <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center font-bold mr-3">
                      {patient?.fullName[0]}
                    </div>
                    <div>
                      <p className="font-semibold text-slate-800">{patient?.fullName || 'Paciente'}</p>
                      <p className="text-xs text-slate-500">{app.time} - {app.location}</p>
                    </div>
                  </div>
                  <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${
                    app.status === AppointmentStatus.CONFIRMADO ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-500'
                  }`}>
                    {app.status}
                  </span>
                </div>
              );
            }) : (
              <div className="p-12 text-center text-slate-400">
                <Calendar className="mx-auto mb-3 opacity-20" size={48} />
                <p>Nenhuma consulta para hoje</p>
              </div>
            )}
          </div>
        </div>

        {/* Pending Approvals */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center">
            <h3 className="font-bold text-lg">Pendentes de Aprovação</h3>
            <span className="text-xs font-bold bg-amber-50 text-amber-600 px-2 py-1 rounded">{pendingAppointments.length}</span>
          </div>
          <div className="divide-y divide-slate-100 max-h-[400px] overflow-y-auto">
            {pendingAppointments.length > 0 ? pendingAppointments.map(app => {
              const patient = patients.find(p => p.id === app.patientId);
              return (
                <div key={app.id} className="p-4 flex items-center justify-between">
                  <div>
                    <p className="font-semibold text-slate-800">{patient?.fullName || 'Paciente'}</p>
                    <p className="text-xs text-slate-500">{formatDate(app.date)} às {app.time}</p>
                  </div>
                  <div className="flex gap-2">
                    <button 
                      onClick={() => updateAppointmentStatus(app.id, AppointmentStatus.CONFIRMADO)}
                      className="bg-green-600 text-white p-1.5 rounded hover:bg-green-700"
                    >
                      ✓
                    </button>
                    <button 
                      onClick={() => updateAppointmentStatus(app.id, AppointmentStatus.DESMARCADO)}
                      className="bg-red-600 text-white p-1.5 rounded hover:bg-red-700"
                    >
                      ✕
                    </button>
                  </div>
                </div>
              );
            }) : (
              <div className="p-12 text-center text-slate-400">
                <AlertCircle className="mx-auto mb-3 opacity-20" size={48} />
                <p>Nenhuma pendência</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { AppointmentStatus, UserRole } from '../types';
import { Calendar as CalendarIcon, Clock, MapPin, Plus } from 'lucide-react';
import { formatDate } from '../utils/helpers';

const Agenda: React.FC = () => {
  const { patients, appointments, addAppointment, currentUser } = useApp();
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    patientId: '',
    date: new Date().toISOString().split('T')[0],
    time: '09:00',
    location: 'Consultório 1',
    status: AppointmentStatus.A_CONFIRMAR
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    addAppointment(formData);
    setShowModal(false);
  };

  const filteredAppointments = currentUser?.role === UserRole.PACIENTE
    ? appointments.filter(a => {
        const p = patients.find(pat => pat.email === currentUser.email);
        return a.patientId === p?.id;
      })
    : appointments;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold">Gerenciamento de Agenda</h2>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center hover:bg-indigo-700"
        >
          <Plus size={20} className="mr-2" />
          Novo Agendamento
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredAppointments.length > 0 ? filteredAppointments.sort((a,b) => b.date.localeCompare(a.date)).map(app => {
          const patient = patients.find(p => p.id === app.patientId);
          return (
            <div key={app.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:border-indigo-200 transition-colors">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h4 className="font-bold text-slate-900">{patient?.fullName || 'Paciente Não Identificado'}</h4>
                  <p className="text-xs text-slate-400">Paciente ID: {app.patientId}</p>
                </div>
                <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${
                  app.status === AppointmentStatus.CONFIRMADO ? 'bg-green-100 text-green-700' : 
                  app.status === AppointmentStatus.A_CONFIRMAR ? 'bg-amber-100 text-amber-700' : 'bg-red-100 text-red-700'
                }`}>
                  {app.status}
                </span>
              </div>

              <div className="space-y-2 mb-6">
                <div className="flex items-center text-sm text-slate-500">
                  <CalendarIcon size={16} className="mr-2" />
                  {formatDate(app.date)}
                </div>
                <div className="flex items-center text-sm text-slate-500">
                  <Clock size={16} className="mr-2" />
                  {app.time}
                </div>
                <div className="flex items-center text-sm text-slate-500">
                  <MapPin size={16} className="mr-2" />
                  {app.location}
                </div>
              </div>

              {currentUser?.role !== UserRole.PACIENTE && (
                <div className="flex gap-2">
                  <button className="flex-1 text-xs font-bold py-2 border border-slate-100 rounded hover:bg-slate-50">Editar</button>
                  <button className="flex-1 text-xs font-bold py-2 bg-indigo-50 text-indigo-600 rounded hover:bg-indigo-100">Prontuário</button>
                </div>
              )}
            </div>
          );
        }) : (
          <div className="col-span-full py-20 text-center text-slate-400">
            Nenhum agendamento encontrado.
          </div>
        )}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-2xl w-full max-w-md p-8 shadow-2xl">
            <h2 className="text-2xl font-bold mb-6">Agendar Consulta</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              {currentUser?.role !== UserRole.PACIENTE ? (
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Selecionar Paciente</label>
                  <select 
                    required
                    className="w-full p-2 border border-slate-200 rounded-lg"
                    value={formData.patientId}
                    onChange={e => setFormData({...formData, patientId: e.target.value})}
                  >
                    <option value="">Selecione um paciente...</option>
                    {patients.map(p => (
                      <option key={p.id} value={p.id}>{p.fullName}</option>
                    ))}
                  </select>
                </div>
              ) : (
                <p className="text-sm font-semibold text-slate-600">
                  Agendando para: {currentUser.name}
                </p>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Data</label>
                  <input 
                    required
                    type="date" 
                    className="w-full p-2 border border-slate-200 rounded-lg"
                    value={formData.date}
