import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { TriageStatus, AppointmentStatus } from '../types';
import { Stethoscope, CheckCircle, ArrowRight, XCircle } from 'lucide-react';
import { formatDate } from '../utils/helpers';

const Triage: React.FC = () => {
  const { appointments, patients, triages, addTriage } = useApp();
  const [showModal, setShowModal] = useState(false);
  const [selectedApp, setSelectedApp] = useState<string>('');
  const [status, setStatus] = useState<TriageStatus>(TriageStatus.PASSA);

  // Somente agendamentos confirmados podem ir para triagem
  const eligibleAppointments = appointments.filter(a => 
    a.status === AppointmentStatus.CONFIRMADO && 
    !triages.some(t => t.appointmentId === a.id)
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const app = appointments.find(a => a.id === selectedApp);
    if (!app) return;

    addTriage({
      appointmentId: selectedApp,
      date: app.date,
      time: app.time,
      location: app.location,
      status
    });
    setShowModal(false);
    setSelectedApp('');
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold">Triagem / Acolhimento</h2>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center hover:bg-indigo-700"
        >
          <Stethoscope size={20} className="mr-2" />
          Realizar Triagem
        </button>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Paciente / Data</th>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Local</th>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Status</th>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Ação</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {triages.length > 0 ? triages.map(t => {
              const app = appointments.find(a => a.id === t.appointmentId);
              const patient = patients.find(p => p.id === app?.patientId);
              return (
                <tr key={t.id} className="hover:bg-slate-50">
                  <td className="px-6 py-4">
                    <div className="font-semibold">{patient?.fullName || 'Desconhecido'}</div>
                    <div className="text-xs text-slate-400">{formatDate(t.date)} às {t.time}</div>
                  </td>
                  <td className="px-6 py-4 text-slate-600">{t.location}</td>
                  <td className="px-6 py-4">
                    <div className="flex items-center">
                      {t.status === TriageStatus.PASSA && <CheckCircle size={16} className="text-green-500 mr-2" />}
                      {t.status === TriageStatus.ENCAMINHA && <ArrowRight size={16} className="text-blue-500 mr-2" />}
                      {t.status === TriageStatus.FALHA && <XCircle size={16} className="text-red-500 mr-2" />}
                      <span className="font-medium">{t.status}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <button className="text-indigo-600 hover:text-indigo-800 text-sm font-medium">Ver Detalhes</button>
                  </td>
                </tr>
              );
            }) : (
              <tr>
                <td colSpan={4} className="px-6 py-12 text-center text-slate-400">Nenhuma triagem realizada.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-2xl w-full max-w-md p-8 shadow-2xl">
            <h2 className="text-2xl font-bold mb-6">Nova Triagem</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Selecionar Agendamento Confirmado</label>
                <select 
                  required
                  className="w-full p-2 border border-slate-200 rounded-lg"
                  value={selectedApp}
                  onChange={e => setSelectedApp(e.target.value)}
                >
                  <option value="">Selecione...</option>
                  {eligibleAppointments.map(a => {
                    const p = patients.find(pat => pat.id === a.patientId);
                    return <option key={a.id} value={a.id}>{p?.fullName} - {formatDate(a.date)}</option>;
                  })}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Resultado da Triagem</label>
                <div className="grid grid-cols-3 gap-2">
                  {Object.values(TriageStatus).map(s => (
                    <button
                      key={s}
                      type="button"
                      onClick={() => setStatus(s)}
                      className={`py-2 px-1 rounded-lg text-xs font-bold transition-all ${
                        status === s ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-600'
                      }`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex gap-4 mt-8">
                <button 
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 px-4 py-2 border border-slate-200 rounded-lg text-slate-600 hover:bg-slate-50"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  disabled={!selectedApp}
                  className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50"
                >
                  Salvar Triagem
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Triage;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { RecordType, AppointmentStatus } from '../types';
import { FilePlus, FileText, Search } from 'lucide-react';
import { formatDate } from '../utils/helpers';

const Records: React.FC = () => {
  const { appointments, patients, records, addMedicalRecord } = useApp();
  const [showModal, setShowModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedApp, setSelectedApp] = useState('');
  const [recordType, setRecordType] = useState(RecordType.CONSULTA_AVALIACAO);
  const [notes, setNotes] = useState('');

  const eligibleApps = appointments.filter(a => a.status === AppointmentStatus.CONFIRMADO);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    addMedicalRecord({
      appointmentId: selectedApp,
      type: recordType,
      details: { notes }
    });
    setShowModal(false);
    setSelectedApp('');
    setNotes('');
  };

  const filteredRecords = records.filter(r => {
    const app = appointments.find(a => a.id === r.appointmentId);
    const patient = patients.find(p => p.id === app?.patientId);
    return patient?.fullName.toLowerCase().includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center gap-4">
         <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Buscar por paciente..." 
            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center hover:bg-indigo-700"
        >
          <FilePlus size={20} className="mr-2" />
          Novo Registro
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredRecords.length > 0 ? filteredRecords.map(rec => {
          const app = appointments.find(a => a.id === rec.appointmentId);
          const patient = patients.find(p => p.id === app?.patientId);
          return (
            <div key={rec.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
              <div className="flex justify-between mb-4">
                <span className="bg-indigo-50 text-indigo-700 px-2 py-1 rounded text-[10px] font-bold uppercase">{rec.type}</span>
                <span className="text-xs text-slate-400">{formatDate(rec.createdAt)}</span>
              </div>
              <h4 className="font-bold text-slate-900 mb-2">{patient?.fullName}</h4>
              <p className="text-sm text-slate-600 line-clamp-3 mb-4">{rec.details.notes}</p>
              <button className="text-indigo-600 text-sm font-bold hover:underline">Ver registro completo</button>
            </div>
          );
        }) : (
          <div className="col-span-full py-20 text-center text-slate-400">Nenhum prontuário encontrado.</div>
