      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-2xl w-full max-w-2xl p-8 shadow-2xl overflow-y-auto max-h-[90vh]">
            <h2 className="text-2xl font-bold mb-6">Novo Registro no Prontuário</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Agendamento</label>
                  <select 
                    required
                    className="w-full p-2 border border-slate-200 rounded-lg"
                    value={selectedApp}
                    onChange={e => setSelectedApp(e.target.value)}
                  >
                    <option value="">Selecione...</option>
                    {eligibleApps.map(a => {
                      const p = patients.find(pat => pat.id === a.patientId);
                      return <option key={a.id} value={a.id}>{p?.fullName} - {formatDate(a.date)}</option>;
                    })}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Tipo de Registro</label>
                  <select 
                    className="w-full p-2 border border-slate-200 rounded-lg"
                    value={recordType}
