import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { RecordType, AppointmentStatus } from '../types';
import { FilePlus, FileText, Search, PlusCircle, Trash2 } from 'lucide-react';
import { formatDate } from '../utils/helpers';

const Records: React.FC = () => {
  const { appointments, patients, records, addMedicalRecord } = useApp();
  const [showModal, setShowModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedApp, setSelectedApp] = useState('');
  const [recordType, setRecordType] = useState(RecordType.CONSULTA_AVALIACAO);

  // Evaluation Specific Fields
  const [evaluationData, setEvaluationData] = useState({
    profissao: '',
    nomeMae: '',
    nomePai: '',
    queixaPrincipal: '',
    exameSolicitado: '',
    quantidadeSessao: 1,
  });
  const [notes, setNotes] = useState('');

  const eligibleApps = appointments.filter(a => a.status === AppointmentStatus.CONFIRMADO);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const app = appointments.find(a => a.id === selectedApp);
    if (!app) return;

    addMedicalRecord({
      appointmentId: selectedApp,
      type: recordType,
      details: recordType === RecordType.CONSULTA_AVALIACAO 
        ? { ...evaluationData, notes }
        : { notes }
    });

    setShowModal(false);
    setSelectedApp('');
    setNotes('');
    setEvaluationData({
      profissao: '',
      nomeMae: '',
      nomePai: '',
      queixaPrincipal: '',
      exameSolicitado: '',
      quantidadeSessao: 1,
    });
  };

  const filteredRecords = records.filter(r => {
    const app = appointments.find(a => a.id === r.appointmentId);
    const patient = patients.find(p => p.id === app?.patientId);
    return patient?.fullName.toLowerCase().includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center gap-4">
         <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Buscar por paciente..." 
            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center hover:bg-indigo-700"
        >
          <FilePlus size={20} className="mr-2" />
          Novo Registro
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredRecords.length > 0 ? filteredRecords.sort((a,b) => b.createdAt.localeCompare(a.createdAt)).map(rec => {
          const app = appointments.find(a => a.id === rec.appointmentId);
          const patient = patients.find(p => p.id === app?.patientId);
          return (
            <div key={rec.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-all">
              <div className="flex justify-between mb-4">
                <span className="bg-indigo-50 text-indigo-700 px-2 py-1 rounded text-[10px] font-bold uppercase">{rec.type}</span>
                <span className="text-xs text-slate-400">{formatDate(rec.createdAt)}</span>
              </div>
              <h4 className="font-bold text-slate-900 mb-1">{patient?.fullName}</h4>
              <p className="text-xs text-slate-400 mb-4">{patient?.age} anos | {rec.type}</p>

              <div className="text-sm text-slate-600 line-clamp-3 mb-4 italic">
                {rec.type === RecordType.CONSULTA_AVALIACAO ? rec.details.queixaPrincipal : rec.details.notes}
              </div>

              <button className="w-full py-2 bg-slate-50 text-slate-600 rounded-lg text-xs font-bold hover:bg-slate-100">
                Ver Detalhes
              </button>
            </div>
          );
        }) : (
          <div className="col-span-full py-20 text-center text-slate-400">
             <FileText size={48} className="mx-auto mb-4 opacity-20" />
             Nenhum prontuário encontrado.
          </div>
        )}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-2xl w-full max-w-3xl p-8 shadow-2xl overflow-y-auto max-h-[90vh]">
            <h2 className="text-2xl font-bold mb-6">Prontuário Clínico</h2>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Agendamento Confirmado</label>
                  <select 
                    required
                    className="w-full p-2 border border-slate-200 rounded-lg"
                    value={selectedApp}
                    onChange={e => setSelectedApp(e.target.value)}
                  >
                    <option value="">Selecione...</option>
                    {eligibleApps.map(a => {
                      const p = patients.find(pat => pat.id === a.patientId);
                      return <option key={a.id} value={a.id}>{p?.fullName} - {formatDate(a.date)}</option>;
                    })}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Tipo de Registro</label>
                  <select 
                    className="w-full p-2 border border-slate-200 rounded-lg"
                    value={recordType}
                    onChange={e => setRecordType(e.target.value as RecordType)}
                  >
                    {Object.values(RecordType).map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
              </div>

              {recordType === RecordType.CONSULTA_AVALIACAO && (
                <div className="p-4 bg-slate-50 rounded-xl space-y-4 border border-slate-100">
                  <h4 className="font-bold text-slate-700 text-sm uppercase tracking-wide">Detalhes da Avaliação</h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1">Profissão</label>
                      <input 
                        type="text" className="w-full p-2 border border-slate-200 rounded-lg" 
                        value={evaluationData.profissao}
                        onChange={e => setEvaluationData({...evaluationData, profissao: e.target.value})}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1">Quantidade de Sessões Previstas</label>
                      <input 
                        type="number" className="w-full p-2 border border-slate-200 rounded-lg" 
                        value={evaluationData.quantidadeSessao}
                        onChange={e => setEvaluationData({...evaluationData, quantidadeSessao: parseInt(e.target.value)})}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1">Nome da Mãe</label>
                      <input 
                        type="text" className="w-full p-2 border border-slate-200 rounded-lg" 
                        value={evaluationData.nomeMae}
                        onChange={e => setEvaluationData({...evaluationData, nomeMae: e.target.value})}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1">Nome do Pai</label>
                      <input 
                        type="text" className="w-full p-2 border border-slate-200 rounded-lg" 
                        value={evaluationData.nomePai}
                        onChange={e => setEvaluationData({...evaluationData, nomePai: e.target.value})}
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-500 mb-1">Queixa Principal</label>
                    <textarea 
                      className="w-full p-2 border border-slate-200 rounded-lg" rows={2}
                      value={evaluationData.queixaPrincipal}
                      onChange={e => setEvaluationData({...evaluationData, queixaPrincipal: e.target.value})}
                    />
                  </div>
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Notas Clínicas / Evolução</label>
                <textarea 
                  required
                  rows={5}
                  className="w-full p-3 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                  placeholder="Descreva os achados clínicos..."
