                    {app.status}
                  </span>
                </div>
              )) : <p className="text-slate-500 italic">Nenhum agendamento encontrado.</p>}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, i) => (
