                      ✕
                    </button>
                  </div>
                </div>
              );
            }) : (
              <div className="p-12 text-center text-slate-400 italic">
                <p className="text-sm">Tudo em dia!</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { PaymentMethod, Transaction, AppointmentStatus } from '../types';
import { CreditCard, Download, Plus, Wallet, TrendingUp, TrendingDown, FileCheck, Send } from 'lucide-react';
import { formatCurrency, formatDate } from '../utils/helpers';

const Finance: React.FC = () => {
  const { transactions, appointments, patients, addTransaction } = useApp();
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    appointmentId: '',
    type: 'RECEBIDO' as Transaction['type'],
    description: 'Consulta Fonoaudiológica',
    value: 150,
    method: PaymentMethod.PIX,
    date: new Date().toISOString().split('T')[0]
  });

  const totals = {
    recebido: transactions.filter(t => t.type === 'RECEBIDO').reduce((acc, t) => acc + t.value, 0),
    receber: transactions.filter(t => t.type === 'RECEBER').reduce((acc, t) => acc + t.value, 0),
    pagar: transactions.filter(t => t.type === 'PAGAR').reduce((acc, t) => acc + t.value, 0),
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const app = appointments.find(a => a.id === formData.appointmentId);
    addTransaction({
      ...formData,
      patientId: app?.patientId || ''
    });
    setShowModal(false);
  };

  const emitReceipt = (t: Transaction) => {
    const patient = patients.find(p => p.id === t.patientId);
    alert(`Recibo Emitido!\n\nPaciente: ${patient?.fullName || 'N/A'}\nValor: ${formatCurrency(t.value)}\nData: ${formatDate(t.date)}\nForma: ${t.method}`);
  };

  const sendReminder = (t: Transaction) => {
    const patient = patients.find(p => p.id === t.patientId);
    alert(`Lembrete de Pagamento enviado para ${patient?.fullName || 'o paciente'} via WhatsApp!\n\nValor: ${formatCurrency(t.value)}\nVencimento: ${formatDate(t.date)}`);
  };

  return (
    <div className="space-y-8">
      {/* Financial Summary */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-start mb-4">
            <div className="bg-emerald-100 text-emerald-600 p-2 rounded-lg"><TrendingUp size={20} /></div>
            <span className="text-xs font-bold text-slate-400">RECEBIDO</span>
          </div>
          <p className="text-2xl font-bold text-emerald-600">{formatCurrency(totals.recebido)}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-start mb-4">
            <div className="bg-amber-100 text-amber-600 p-2 rounded-lg"><Wallet size={20} /></div>
            <span className="text-xs font-bold text-slate-400">A RECEBER</span>
          </div>
          <p className="text-2xl font-bold text-amber-600">{formatCurrency(totals.receber)}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-start mb-4">
            <div className="bg-rose-100 text-rose-600 p-2 rounded-lg"><TrendingDown size={20} /></div>
            <span className="text-xs font-bold text-slate-400">CONTAS A PAGAR</span>
          </div>
          <p className="text-2xl font-bold text-rose-600">{formatCurrency(totals.pagar)}</p>
        </div>
      </div>

      <div className="flex justify-between items-center">
        <h3 className="text-xl font-bold">Transações Recentes</h3>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center hover:bg-indigo-700"
        >
          <Plus size={20} className="mr-2" />
          Nova Transação
        </button>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Data</th>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Descrição</th>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Tipo</th>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Valor</th>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {transactions.length > 0 ? transactions.sort((a,b) => b.date.localeCompare(a.date)).map(t => (
              <tr key={t.id} className="hover:bg-slate-50">
                <td className="px-6 py-4 text-sm">{formatDate(t.date)}</td>
                <td className="px-6 py-4">
                  <div className="text-sm font-medium">{t.description}</div>
                  <div className="text-xs text-slate-400">{t.method}</div>
                </td>
                <td className="px-6 py-4 text-sm font-bold">
                  <span className={`px-2 py-1 rounded-full text-[10px] uppercase ${
                    t.type === 'RECEBIDO' ? 'bg-green-100 text-green-700' : 
                    t.type === 'RECEBER' ? 'bg-amber-100 text-amber-700' : 'bg-rose-100 text-rose-700'
                  }`}>
                    {t.type}
                  </span>
                </td>
                <td className={`px-6 py-4 text-sm font-bold ${t.type === 'PAGAR' ? 'text-rose-600' : 'text-emerald-600'}`}>
                  {t.type === 'PAGAR' ? '-' : '+'}{formatCurrency(t.value)}
                </td>
                <td className="px-6 py-4">
                  <div className="flex gap-3">
                    {t.type === 'RECEBIDO' && (
                      <button 
                        onClick={() => emitReceipt(t)}
                        className="text-indigo-600 hover:text-indigo-800 flex items-center gap-1 text-xs font-bold"
                      >
                        <FileCheck size={14} /> Recibo
                      </button>
                    )}
                    {t.type === 'RECEBER' && (
                      <button 
                        onClick={() => sendReminder(t)}
                        className="text-amber-600 hover:text-amber-800 flex items-center gap-1 text-xs font-bold"
                      >
                        <Send size={14} /> Lembrar
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            )) : (
              <tr>
                <td colSpan={5} className="px-6 py-12 text-center text-slate-400">Nenhuma transação registrada.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-2xl w-full max-w-md p-8 shadow-2xl">
            <h2 className="text-2xl font-bold mb-6">Lançar Financeiro</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Agendamento Relacionado</label>
                <select 
                  required
                  className="w-full p-2 border border-slate-200 rounded-lg"
                  value={formData.appointmentId}
                  onChange={e => setFormData({...formData, appointmentId: e.target.value})}
                >
                  <option value="">Selecione...</option>
                  {appointments.filter(a => a.status === AppointmentStatus.CONFIRMADO).map(a => {
                    const p = patients.find(pat => pat.id === a.patientId);
                    return <option key={a.id} value={a.id}>{p?.fullName} - {formatDate(a.date)}</option>;
                  })}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Tipo</label>
                  <select 
                    className="w-full p-2 border border-slate-200 rounded-lg"
                    value={formData.type}
                    onChange={e => setFormData({...formData, type: e.target.value as any})}
                  >
                    <option value="RECEBIDO">Recebido</option>
                    <option value="RECEBER">A Receber</option>
                    <option value="PAGAR">A Pagar</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Valor (R$)</label>
                  <input 
                    required
                    type="number" 
                    className="w-full p-2 border border-slate-200 rounded-lg"
                    value={formData.value}
                    onChange={e => setFormData({...formData, value: parseFloat(e.target.value)})}
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Forma de Pagamento</label>
                <select 
                  className="w-full p-2 border border-slate-200 rounded-lg"
                  value={formData.method}
                  onChange={e => setFormData({...formData, method: e.target.value as PaymentMethod})}
                >
                  {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Descrição</label>
                <input 
                  required
                  className="w-full p-2 border border-slate-200 rounded-lg"
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                />
              </div>

              <div className="flex gap-4 mt-8">
                <button 
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 px-4 py-2 border border-slate-200 rounded-lg text-slate-600 hover:bg-slate-50"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                >
                  Salvar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Finance;

