                </div>
              </div>
              <div className="flex gap-4 mt-8">
                <button 
                  type="button"
                  onClick={closeModals}
                  className="flex-1 px-4 py-3 border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 font-bold transition-colors"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 font-bold transition-all shadow-lg shadow-indigo-100"
                >
                  {isEditing ? 'Salvar Alterações' : 'Cadastrar'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Patients;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { AppointmentStatus, UserRole } from '../types';
import { Calendar as CalendarIcon, Clock, MapPin, Plus, Pencil, Trash2, X, Check } from 'lucide-react';
import { formatDate } from '../utils/helpers';

const Agenda: React.FC = () => {
  const { patients, appointments, addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, currentUser } = useApp();
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [selectedAppId, setSelectedAppId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    patientId: '',
    date: new Date().toISOString().split('T')[0],
    time: '09:00',
    location: 'Consultório 1',
    status: AppointmentStatus.A_CONFIRMAR
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isEditing && selectedAppId) {
      updateAppointment(selectedAppId, formData);
    } else {
      addAppointment(formData);
    }
    closeModal();
  };

  const closeModal = () => {
    setShowModal(false);
    setIsEditing(false);
    setSelectedAppId(null);
    setFormData({
      patientId: '',
      date: new Date().toISOString().split('T')[0],
      time: '09:00',
      location: 'Consultório 1',
      status: AppointmentStatus.A_CONFIRMAR
    });
  };

  const handleEditClick = (app: any) => {
    setFormData({
      patientId: app.patientId,
      date: app.date,
      time: app.time,
      location: app.location,
      status: app.status
    });
    setSelectedAppId(app.id);
    setIsEditing(true);
    setShowModal(true);
  };

  const handleDeleteClick = (id: string) => {
    if (window.confirm('Excluir agendamento permanentemente?')) {
      deleteAppointment(id);
    }
  };

  const filteredAppointments = currentUser?.role === UserRole.PACIENTE
    ? appointments.filter(a => {
        const p = patients.find(pat => pat.email === currentUser.email);
        return a.patientId === p?.id;
      })
    : appointments;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-800">Gerenciamento de Agenda</h2>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center hover:bg-indigo-700 shadow-md transition-all"
        >
          <Plus size={20} className="mr-2" />
          Novo Agendamento
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredAppointments.length > 0 ? filteredAppointments.sort((a,b) => b.date.localeCompare(a.date)).map(app => {
          const patient = patients.find(p => p.id === app.patientId);
          return (
            <div key={app.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:border-indigo-200 transition-all relative group">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h4 className="font-bold text-slate-900">{patient?.fullName || 'Paciente Removido'}</h4>
                  <p className="text-[10px] text-slate-400 font-bold uppercase">ID: {app.patientId}</p>
                </div>
                <div className="flex flex-col items-end gap-2">
                  <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${
                    app.status === AppointmentStatus.CONFIRMADO ? 'bg-green-100 text-green-700' : 
                    app.status === AppointmentStatus.A_CONFIRMAR ? 'bg-amber-100 text-amber-700' : 
                    app.status === AppointmentStatus.DESMARCADO ? 'bg-rose-100 text-rose-700' : 'bg-slate-100 text-slate-600'
                  }`}>
                    {app.status}
                  </span>
                </div>
              </div>

              <div className="space-y-2 mb-6">
                <div className="flex items-center text-sm text-slate-500">
                  <CalendarIcon size={16} className="mr-2 text-indigo-400" />
                  {formatDate(app.date)}
                </div>
                <div className="flex items-center text-sm text-slate-500">
                  <Clock size={16} className="mr-2 text-indigo-400" />
                  {app.time}
                </div>
                <div className="flex items-center text-sm text-slate-500">
                  <MapPin size={16} className="mr-2 text-indigo-400" />
                  {app.location}
                </div>
              </div>

              {currentUser?.role !== UserRole.PACIENTE && (
                <div className="flex gap-2">
                  <button 
                    onClick={() => handleEditClick(app)}
                    className="flex-1 flex items-center justify-center gap-2 text-xs font-bold py-2 bg-slate-50 text-slate-600 rounded-lg hover:bg-slate-100 transition-colors"
                  >
                    <Pencil size={14} /> Editar
                  </button>
                  <button 
                    onClick={() => handleDeleteClick(app.id)}
                    className="p-2 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100 transition-colors"
                    title="Excluir"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              )}
            </div>
          );
        }) : (
          <div className="col-span-full py-20 text-center text-slate-400">
            <CalendarIcon size={48} className="mx-auto mb-4 opacity-10" />
            Nenhum agendamento encontrado.
          </div>
        )}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-slate-800">{isEditing ? 'Alterar Agendamento' : 'Novo Agendamento'}</h2>
              <button onClick={closeModal} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-4">
              {currentUser?.role !== UserRole.PACIENTE ? (
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Selecionar Paciente</label>
                  <select 
                    required
                    className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.patientId}
                    onChange={e => setFormData({...formData, patientId: e.target.value})}
                  >
                    <option value="">Selecione um paciente...</option>
                    {patients.map(p => (
                      <option key={p.id} value={p.id}>{p.fullName}</option>
                    ))}
                  </select>
                </div>
              ) : (
                <div className="p-3 bg-indigo-50 rounded-xl mb-4">
                  <p className="text-xs text-indigo-400 font-bold uppercase mb-1">Paciente</p>
                  <p className="font-semibold text-indigo-800">{currentUser.name}</p>
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Data</label>
                  <input 
                    required
                    type="date" 
                    className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.date}
                    onChange={e => setFormData({...formData, date: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Horário</label>
                  <input 
                    required
                    type="time" 
                    className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.time}
                    onChange={e => setFormData({...formData, time: e.target.value})}
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Local</label>
                <select 
                  className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                  value={formData.location}
                  onChange={e => setFormData({...formData, location: e.target.value})}
                >
                  <option>Consultório 1</option>
                  <option>Consultório 2</option>
                  <option>Sala de Exames</option>
                  <option>Sala de Triagem</option>
                </select>
              </div>

              {isEditing && (
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Status</label>
                  <select 
                    className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.status}
                    onChange={e => setFormData({...formData, status: e.target.value as AppointmentStatus})}
                  >
                    {Object.values(AppointmentStatus).map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
              )}

              <div className="flex gap-4 mt-8">
                <button 
                  type="button"
                  onClick={closeModal}
                  className="flex-1 px-4 py-3 border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 font-bold transition-all"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 font-bold shadow-lg shadow-indigo-100 transition-all"
                >
                  {isEditing ? 'Salvar Alterações' : 'Confirmar Agenda'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Agenda;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { TriageStatus, AppointmentStatus } from '../types';
import { Stethoscope, CheckCircle, ArrowRight, XCircle, Trash2, Eye, X } from 'lucide-react';
import { formatDate } from '../utils/helpers';

const Triage: React.FC = () => {
  const { appointments, patients, triages, addTriage, deleteTriage } = useApp();
  const [showModal, setShowModal] = useState(false);
  const [showViewModal, setShowViewModal] = useState(false);
  const [selectedTriageId, setSelectedTriageId] = useState<string | null>(null);
  const [selectedApp, setSelectedApp] = useState<string>('');
  const [status, setStatus] = useState<TriageStatus>(TriageStatus.PASSA);

  const eligibleAppointments = appointments.filter(a => 
    a.status === AppointmentStatus.CONFIRMADO && 
    !triages.some(t => t.appointmentId === a.id)
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const app = appointments.find(a => a.id === selectedApp);
    if (!app) return;

    addTriage({
      appointmentId: selectedApp,
      date: app.date,
      time: app.time,
      location: app.location,
      status
    });
    setShowModal(false);
    setSelectedApp('');
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Excluir este registro de triagem?')) {
      deleteTriage(id);
    }
  };

  const handleView = (id: string) => {
    setSelectedTriageId(id);
    setShowViewModal(true);
  };

  const selectedTriage = triages.find(t => t.id === selectedTriageId);
  const selectedAppInfo = appointments.find(a => a.id === selectedTriage?.appointmentId);
  const patientInfo = patients.find(p => p.id === selectedAppInfo?.patientId);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-800">Triagem / Acolhimento</h2>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center hover:bg-indigo-700 shadow-md transition-all"
        >
          <Stethoscope size={20} className="mr-2" />
          Realizar Triagem
        </button>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Paciente / Data</th>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Local</th>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase">Status</th>
              <th className="px-6 py-4 font-bold text-sm text-slate-500 uppercase text-center">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {triages.length > 0 ? triages.map(t => {
              const app = appointments.find(a => a.id === t.appointmentId);
              const patient = patients.find(p => p.id === app?.patientId);
              return (
                <tr key={t.id} className="hover:bg-slate-50 group">
                  <td className="px-6 py-4">
                    <div className="font-semibold text-slate-800">{patient?.fullName || 'Desconhecido'}</div>
                    <div className="text-xs text-slate-400 font-bold uppercase">{formatDate(t.date)} • {t.time}</div>
                  </td>
                  <td className="px-6 py-4 text-slate-600 text-sm">{t.location}</td>
                  <td className="px-6 py-4">
                    <div className="flex items-center">
                      {t.status === TriageStatus.PASSA && <CheckCircle size={16} className="text-green-500 mr-2" />}
                      {t.status === TriageStatus.ENCAMINHA && <ArrowRight size={16} className="text-blue-500 mr-2" />}
                      {t.status === TriageStatus.FALHA && <XCircle size={16} className="text-red-500 mr-2" />}
                      <span className="font-bold text-xs uppercase text-slate-700">{t.status}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center justify-center gap-2">
                      <button 
                        onClick={() => handleView(t.id)}
                        className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                      >
                        <Eye size={18} />
                      </button>
                      <button 
                        onClick={() => handleDelete(t.id)}
                        className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              );
            }) : (
              <tr>
                <td colSpan={4} className="px-6 py-12 text-center text-slate-400">Nenhuma triagem realizada.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {showViewModal && selectedTriage && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200">
             <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-slate-800">Detalhes da Triagem</h2>
              <button onClick={() => setShowViewModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>
            <div className="space-y-4">
               <div className="p-4 bg-slate-50 rounded-xl">
                  <p className="text-xs text-slate-400 font-bold uppercase mb-1">Paciente</p>
                  <p className="font-bold text-slate-800">{patientInfo?.fullName}</p>
               </div>
               <div className="grid grid-cols-2 gap-4">
                 <div className="p-4 bg-slate-50 rounded-xl">
                    <p className="text-xs text-slate-400 font-bold uppercase mb-1">Resultado</p>
                    <p className={`font-bold ${selectedTriage.status === TriageStatus.PASSA ? 'text-green-600' : 'text-indigo-600'}`}>{selectedTriage.status}</p>
                 </div>
                 <div className="p-4 bg-slate-50 rounded-xl">
                    <p className="text-xs text-slate-400 font-bold uppercase mb-1">Horário</p>
                    <p className="font-bold text-slate-800">{selectedTriage.time}</p>
                 </div>
               </div>
               <div className="p-4 bg-slate-50 rounded-xl">
                  <p className="text-xs text-slate-400 font-bold uppercase mb-1">Local da Triagem</p>
                  <p className="font-bold text-slate-800">{selectedTriage.location}</p>
               </div>
            </div>
          </div>
        </div>
      )}

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <h2 className="text-2xl font-bold mb-6 text-slate-800">Nova Triagem</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Selecionar Agendamento Confirmado</label>
                <select 
                  required
                  className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                  value={selectedApp}
                  onChange={e => setSelectedApp(e.target.value)}
                >
                  <option value="">Selecione...</option>
                  {eligibleAppointments.map(a => {
                    const p = patients.find(pat => pat.id === a.patientId);
                    return <option key={a.id} value={a.id}>{p?.fullName} - {formatDate(a.date)}</option>;
                  })}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Resultado da Triagem</label>
                <div className="grid grid-cols-3 gap-2">
                  {Object.values(TriageStatus).map(s => (
                    <button
                      key={s}
                      type="button"
                      onClick={() => setStatus(s)}
                      className={`py-3 px-1 rounded-xl text-[10px] font-bold transition-all border-2 ${
                        status === s ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-500'
                      }`}
                    >
                      {s.toUpperCase()}
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex gap-4 mt-8">
                <button 
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 px-4 py-3 border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 font-bold transition-all"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  disabled={!selectedApp}
                  className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 font-bold shadow-lg shadow-indigo-100 disabled:opacity-50 transition-all"
                >
                  Salvar Triagem
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Triage;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { RecordType, AppointmentStatus } from '../types';
import { FilePlus, FileText, Search, PlusCircle, Trash2, Eye, X } from 'lucide-react';
import { formatDate } from '../utils/helpers';

const Records: React.FC = () => {
  const { appointments, patients, records, addMedicalRecord, deleteMedicalRecord } = useApp();
  const [showModal, setShowModal] = useState(false);
  const [showViewModal, setShowViewModal] = useState(false);
