  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const app = appointments.find(a => a.id === selectedApp);
    if (!app) return;

    addMedicalRecord({
      appointmentId: selectedApp,
      type: recordType,
      details: recordType === RecordType.CONSULTA_AVALIACAO 
        ? { ...evaluationData, notes }
        : { notes }
    });

    setShowModal(false);
    resetForm();
  };

  const resetForm = () => {
    setSelectedApp('');
    setNotes('');
    setRecordType(RecordType.CONSULTA_AVALIACAO);
    setEvaluationData({
      profissao: '',
      nomeMae: '',
      nomePai: '',
      queixaPrincipal: '',
      exameSolicitado: '',
      quantidadeSessao: 1,
    });
  };

  const handleDelete = (id: string) => {
