                    <div>
                      <label className="block text-[10px] font-bold text-slate-400 mb-1">Nome do Pai</label>
                      <input 
                        type="text" className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" 
