import { 
  LayoutDashboard, 
  Users, 
  Calendar, 
  Stethoscope, 
  FileText, 
  CreditCard, 
  BarChart3, 
  MessageSquare, 
  LogOut,
  Menu,
  X,
  Bell,
  AlertCircle
} from 'lucide-react';
import { formatCurrency, formatDate } from '../utils/helpers';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
}

