               {isNotificationsOpen && (
                 <div className="absolute right-0 mt-3 w-80 bg-white rounded-2xl shadow-2xl border border-slate-100 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                   <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                     <h3 className="font-bold text-sm">Alertas e Notificações</h3>
                     <span className="text-[10px] bg-rose-100 text-rose-600 px-2 py-0.5 rounded-full font-bold">{financialAlertsCount}</span>
                   </div>
                   <div className="max-h-[300px] overflow-y-auto divide-y divide-slate-50">
                     {financialAlerts.length > 0 ? financialAlerts.map(t => {
                       const patient = patients.find(p => p.id === t.patientId);
                       return (
                         <div key={t.id} className="p-4 hover:bg-slate-50 transition-colors cursor-pointer" onClick={() => { setActiveTab('finance'); setIsNotificationsOpen(false); }}>
                           <div className="flex gap-3">
                             <div className={`p-2 rounded-lg h-fit ${t.type === 'RECEBER' ? 'bg-amber-100 text-amber-600' : 'bg-rose-100 text-rose-600'}`}>
                               <AlertCircle size={16} />
                             </div>
                             <div>
                               <p className="text-xs font-bold text-slate-800">{t.type === 'RECEBER' ? 'Cobrança Pendente' : 'Pagamento Pendente'}</p>
                               <p className="text-[10px] text-slate-500 mb-1">{patient?.fullName || 'Externo'} - {formatCurrency(t.value)}</p>
                               <p className="text-[9px] text-slate-400 font-semibold">{formatDate(t.date)}</p>
                             </div>
                           </div>
                         </div>
                       );
                     }) : (
                       <div className="p-8 text-center text-slate-400 text-xs italic">
                         Nenhuma notificação importante.
                       </div>
                     )}
                   </div>
                   {financialAlertsCount > 0 && (
                     <button 
                      onClick={() => { setActiveTab('finance'); setIsNotificationsOpen(false); }}
                      className="w-full p-3 text-xs font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 transition-colors text-center"
                     >
                       Ver tudo no Financeiro
                     </button>
                   )}
                 </div>
               )}
             </div>
             <div className="h-8 w-[1px] bg-slate-200"></div>
             <span className="text-sm text-slate-500 hidden sm:block">{new Date().toLocaleDateString('pt-BR', { dateStyle: 'long' })}</span>
          </div>
        </header>

        <div className="p-8 max-w-7xl mx-auto w-full">
          {children}
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
