  });
  const [notes, setNotes] = useState('');
  const [observacoesAdicionais, setObservacoesAdicionais] = useState('');

  const eligibleApps = appointments.filter(a => a.status === AppointmentStatus.CONFIRMADO);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const app = appointments.find(a => a.id === selectedApp);
    if (!app) return;

    addMedicalRecord({
      appointmentId: selectedApp,
      type: recordType,
      details: recordType === RecordType.CONSULTA_AVALIACAO 
        ? { ...evaluationData, notes, observacoesAdicionais }
        : { notes, observacoesAdicionais }
    });

    setShowModal(false);
    resetForm();
  };

  const resetForm = () => {
    setSelectedApp('');
    setNotes('');
    setObservacoesAdicionais('');
    setRecordType(RecordType.CONSULTA_AVALIACAO);
    setEvaluationData({
      profissao: '',
      nomeMae: '',
      nomePai: '',
      queixaPrincipal: '',
      exameSolicitado: '',
      quantidadeSessao: 1,
    });
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Excluir este registro do prontuário permanentemente?')) {
      deleteMedicalRecord(id);
    }
  };

  const handleView = (id: string) => {
    setSelectedRecordId(id);
    setShowViewModal(true);
  };

  const filteredRecords = records.filter(r => {
    const app = appointments.find(a => a.id === r.appointmentId);
    const patient = patients.find(p => p.id === app?.patientId);
    return patient?.fullName.toLowerCase().includes(searchTerm.toLowerCase());
  });

  const currentRecord = records.find(r => r.id === selectedRecordId);
  const recordApp = appointments.find(a => a.id === currentRecord?.appointmentId);
  const recordPatient = patients.find(p => p.id === recordApp?.patientId);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center gap-4">
         <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Buscar por paciente..." 
            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={() => { resetForm(); setShowModal(true); }}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center hover:bg-indigo-700 shadow-md transition-all"
        >
          <FilePlus size={20} className="mr-2" />
          Novo Registro
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredRecords.length > 0 ? filteredRecords.sort((a,b) => b.createdAt.localeCompare(a.createdAt)).map(rec => {
          const app = appointments.find(a => a.id === rec.appointmentId);
          const patient = patients.find(p => p.id === app?.patientId);
          return (
            <div key={rec.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md hover:border-indigo-100 transition-all group">
              <div className="flex justify-between mb-4">
                <span className="bg-indigo-50 text-indigo-700 px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider">{rec.type}</span>
                <span className="text-[10px] text-slate-400 font-bold">{formatDate(rec.createdAt)}</span>
              </div>
              <h4 className="font-bold text-slate-900 mb-1">{patient?.fullName || 'Paciente Removido'}</h4>
              <p className="text-[10px] text-slate-400 mb-4 font-bold uppercase">{patient?.age} anos | {rec.type}</p>

              <div className="text-sm text-slate-600 line-clamp-2 mb-6 italic opacity-70">
                {rec.type === RecordType.CONSULTA_AVALIACAO ? rec.details.queixaPrincipal : rec.details.notes}
              </div>

              <div className="flex gap-2">
                <button 
                  onClick={() => handleView(rec.id)}
                  className="flex-1 py-2 bg-slate-50 text-slate-600 rounded-lg text-xs font-bold hover:bg-indigo-50 hover:text-indigo-600 transition-all flex items-center justify-center gap-2"
                >
                  <Eye size={14} /> Ver
                </button>
                <button 
                   onClick={() => handleDelete(rec.id)}
                   className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          );
        }) : (
          <div className="col-span-full py-20 text-center text-slate-400">
             <FileText size={48} className="mx-auto mb-4 opacity-10" />
             Nenhum prontuário encontrado.
          </div>
        )}
      </div>

      {/* Modal Visualização */}
      {showViewModal && currentRecord && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-2xl p-8 shadow-2xl animate-in zoom-in-95 duration-200 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-slate-800">Detalhes do Prontuário</h2>
              <button onClick={() => setShowViewModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>

            <div className="space-y-6">
               <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-50 rounded-xl">
                    <p className="text-xs text-slate-400 font-bold uppercase mb-1">Paciente</p>
                    <p className="font-bold text-slate-800">{recordPatient?.fullName}</p>
                  </div>
                  <div className="p-4 bg-slate-50 rounded-xl">
                    <p className="text-xs text-slate-400 font-bold uppercase mb-1">Tipo de Registro</p>
                    <p className="font-bold text-indigo-600">{currentRecord.type}</p>
                  </div>
               </div>

               {currentRecord.type === RecordType.CONSULTA_AVALIACAO && (
                 <div className="p-5 bg-indigo-50/50 border border-indigo-100 rounded-2xl space-y-4">
                    <h4 className="text-xs font-bold text-indigo-400 uppercase tracking-widest border-b border-indigo-100 pb-2">Informações da Avaliação</h4>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Profissão</p>
                        <p className="text-sm font-semibold">{currentRecord.details.profissao || 'Não informado'}</p>
                      </div>
                      <div>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Sessões Previstas</p>
                        <p className="text-sm font-semibold">{currentRecord.details.quantidadeSessao}</p>
                      </div>
                      <div>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Mãe / Pai</p>
                        <p className="text-sm font-semibold">{currentRecord.details.nomeMae} / {currentRecord.details.nomePai}</p>
                      </div>
                    </div>
                    <div>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">Queixa Principal</p>
                      <p className="text-sm font-semibold italic">"{currentRecord.details.queixaPrincipal}"</p>
                    </div>
                 </div>
               )}

               <div>
                 <p className="text-xs text-slate-400 font-bold uppercase mb-2">Notas e Evolução</p>
                 <div className="p-5 bg-slate-50 rounded-2xl text-slate-700 text-sm whitespace-pre-wrap leading-relaxed shadow-inner">
                   {currentRecord.details.notes}
                 </div>
               </div>

               {currentRecord.details.observacoesAdicionais && (
                 <div>
                   <p className="text-xs text-slate-400 font-bold uppercase mb-2">Observações Adicionais</p>
                   <div className="p-5 bg-indigo-50/30 border border-indigo-100/50 rounded-2xl text-slate-700 text-sm whitespace-pre-wrap leading-relaxed shadow-inner">
                     {currentRecord.details.observacoesAdicionais}
                   </div>
                 </div>
               )}

               <div className="flex justify-end pt-4">
                 <button 
                  onClick={() => setShowViewModal(false)}
                  className="px-6 py-2 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition-all shadow-md"
                 >
                   Fechar
                 </button>
               </div>
            </div>
          </div>
        </div>
      )}

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-3xl p-8 shadow-2xl animate-in zoom-in-95 duration-200 overflow-y-auto max-h-[90vh]">
            <h2 className="text-2xl font-bold mb-6 text-slate-800">Novo Registro no Prontuário</h2>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1 text-[10px] font-bold uppercase">Agendamento Confirmado</label>
                  <select 
                    required
                    className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50"
                    value={selectedApp}
                    onChange={e => setSelectedApp(e.target.value)}
                  >
                    <option value="">Selecione...</option>
                    {eligibleApps.map(a => {
                      const p = patients.find(pat => pat.id === a.patientId);
                      return <option key={a.id} value={a.id}>{p?.fullName} - {formatDate(a.date)}</option>;
                    })}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1 text-[10px] font-bold uppercase">Tipo de Registro</label>
                  <select 
                    className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50"
                    value={recordType}
                    onChange={e => setRecordType(e.target.value as RecordType)}
                  >
                    {Object.values(RecordType).map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
              </div>

              {recordType === RecordType.CONSULTA_AVALIACAO && (
                <div className="p-6 bg-slate-50 rounded-2xl space-y-4 border border-slate-100 shadow-inner">
                  <h4 className="font-bold text-slate-700 text-xs uppercase tracking-widest border-b border-slate-200 pb-2">Dados da Avaliação</h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-[10px] font-bold text-slate-400 mb-1">Profissão</label>
                      <input 
                        type="text" className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" 
                        value={evaluationData.profissao}
                        onChange={e => setEvaluationData({...evaluationData, profissao: e.target.value})}
                      />
                    </div>
                    <div>
                      <label className="block text-[10px] font-bold text-slate-400 mb-1">Qtd. Sessões Previstas</label>
                      <input 
                        type="number" className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" 
                        value={evaluationData.quantidadeSessao}
                        onChange={e => setEvaluationData({...evaluationData, quantidadeSessao: parseInt(e.target.value)})}
                      />
                    </div>
                    <div>
                      <label className="block text-[10px] font-bold text-slate-400 mb-1">Nome da Mãe</label>
                      <input 
                        type="text" className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" 
                        value={evaluationData.nomeMae}
                        onChange={e => setEvaluationData({...evaluationData, nomeMae: e.target.value})}
                      />
                    </div>
                    <div>
                      <label className="block text-[10px] font-bold text-slate-400 mb-1">Nome do Pai</label>
                      <input 
                        type="text" className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" 
                        value={evaluationData.nomePai}
                        onChange={e => setEvaluationData({...evaluationData, nomePai: e.target.value})}
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-400 mb-1">Queixa Principal</label>
                    <textarea 
                      className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" rows={2}
                      value={evaluationData.queixaPrincipal}
                      onChange={e => setEvaluationData({...evaluationData, queixaPrincipal: e.target.value})}
                    />
                  </div>
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1 text-[10px] font-bold uppercase">Notas Clínicas / Evolução</label>
                <textarea 
                  required
                  rows={4}
                  className="w-full p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm bg-slate-50"
                  placeholder="Descreva detalhadamente o atendimento..."
                  value={notes}
                  onChange={e => setNotes(e.target.value)}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1 text-[10px] font-bold uppercase">Observações Adicionais</label>
                <textarea 
                  rows={4}
                  className="w-full p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm bg-slate-50"
                  placeholder="Insira notas adicionais sobre o atendimento, histórico complementar ou detalhes logísticos..."
                  value={observacoesAdicionais}
                  onChange={e => setObservacoesAdicionais(e.target.value)}
                />
              </div>

              <div className="flex gap-4 mt-8">
                <button 
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 px-4 py-3 border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 font-bold transition-all"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-100 font-bold transition-all"
                >
                  Salvar no Prontuário
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Records;

import React, { useState } from 'react';
import { useApp } from '../store/AppContext';
import { RecordType, AppointmentStatus, Appointment } from '../types';
import { 
  Activity, 
  User, 
  ClipboardList, 
  Save, 
  Stethoscope, 
  Ear, 
  Baby, 
  CheckCircle2,
  Clock,
  History
} from 'lucide-react';
import { formatDate } from '../utils/helpers';

const Clinic: React.FC = () => {
  const { appointments, patients, records, triages, addMedicalRecord } = useApp();
  const [selectedAppId, setSelectedAppId] = useState<string>('');
  const [evolutionNotes, setEvolutionNotes] = useState('');
  const [examDetails, setExamDetails] = useState({
    testeOrelhinha: '',
    testeLinguinha: '',
    audiometria: '',
  });

  const today = new Date().toISOString().split('T')[0];
  const todayApps = appointments.filter(a => a.date === today && a.status === AppointmentStatus.CONFIRMADO);

  const activeApp = appointments.find(a => a.id === selectedAppId);
  const activePatient = patients.find(p => p.id === activeApp?.patientId);
  const activeTriage = triages.find(t => t.appointmentId === selectedAppId);
  const patientHistory = records.filter(r => {
    const app = appointments.find(a => a.id === r.appointmentId);
    return app?.patientId === activePatient?.id;
  });

  const handleFinishSession = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedAppId) return;

    // Determina se é Sessão ou Exame baseado no preenchimento
    const isExam = examDetails.testeOrelhinha || examDetails.testeLinguinha || examDetails.audiometria;

    addMedicalRecord({
      appointmentId: selectedAppId,
      type: isExam ? RecordType.EXAME : RecordType.SESSAO,
      details: {
        notes: evolutionNotes,
        exams: examDetails,
        dataFinalizacao: new Date().toISOString()
      }
    });

    alert('Atendimento finalizado e prontuário atualizado!');
    setEvolutionNotes('');
    setExamDetails({ testeOrelhinha: '', testeLinguinha: '', audiometria: '' });
    setSelectedAppId('');
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
      {/* Sidebar: Seleção e Resumo */}
      <div className="lg:col-span-4 space-y-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Clock size={20} className="text-indigo-600" />
            Pacientes de Hoje
          </h3>
          <div className="space-y-3">
            {todayApps.length > 0 ? todayApps.map(app => {
              const p = patients.find(pat => pat.id === app.patientId);
              return (
                <button
                  key={app.id}
                  onClick={() => setSelectedAppId(app.id)}
                  className={`w-full p-4 rounded-xl border-2 transition-all text-left flex items-center justify-between ${
                    selectedAppId === app.id 
                    ? 'border-indigo-600 bg-indigo-50 shadow-md' 
                    : 'border-slate-50 bg-slate-50 hover:border-indigo-200'
                  }`}
                >
                  <div>
                    <p className="font-bold text-slate-800 text-sm">{p?.fullName}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase">{app.time} • {app.location}</p>
                  </div>
                  {selectedAppId === app.id && <CheckCircle2 size={18} className="text-indigo-600" />}
                </button>
              );
            }) : (
              <p className="text-xs text-slate-400 italic text-center py-4">Nenhum paciente confirmado para hoje.</p>
            )}
          </div>
        </div>

        {activePatient && (
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 animate-in fade-in slide-in-from-left-4">
            <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
              <User size={20} className="text-indigo-600" />
              Ficha Rápida
            </h3>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div className="p-3 bg-slate-50 rounded-lg">
                  <p className="text-[10px] text-slate-400 font-bold uppercase">Idade</p>
                  <p className="text-sm font-bold">{activePatient.age} anos</p>
                </div>
                <div className="p-3 bg-slate-50 rounded-lg">
                  <p className="text-[10px] text-slate-400 font-bold uppercase">Telefone</p>
                  <p className="text-sm font-bold">{activePatient.phone}</p>
                </div>
              </div>

              <div className="p-3 bg-indigo-50/50 rounded-lg border border-indigo-100">
                <p className="text-[10px] text-indigo-400 font-bold uppercase mb-1">Queixa Principal (Triagem)</p>
                <p className="text-xs italic text-indigo-900 leading-relaxed">
                  {activeTriage ? "Paciente com queixa de atraso na fala e dificuldade de deglutição." : "Não realizada na triagem."}
                </p>
              </div>

              <div>
                <p className="text-[10px] text-slate-400 font-bold uppercase mb-2 flex items-center gap-1">
                  <History size={12} /> Últimas Evoluções
                </p>
                <div className="space-y-2 max-h-40 overflow-y-auto pr-2">
                  {patientHistory.slice(0, 3).map(h => (
                    <div key={h.id} className="p-2 border-b border-slate-100 last:border-0">
                      <p className="text-[9px] font-bold text-slate-400">{formatDate(h.createdAt)} - {h.type}</p>
                      <p className="text-[10px] text-slate-600 line-clamp-2">{h.details.notes}</p>
                    </div>
                  ))}
                  {patientHistory.length === 0 && <p className="text-[10px] text-slate-300 italic">Sem histórico prévio.</p>}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Main Area: Evolução */}
      <div className="lg:col-span-8">
        {selectedAppId ? (
          <form onSubmit={handleFinishSession} className="space-y-6 animate-in fade-in zoom-in-95 duration-300">
            <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-100">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-xl font-bold text-slate-800">Evolução do Atendimento</h2>
                <div className="flex gap-2">
                  <span className="bg-emerald-100 text-emerald-700 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest animate-pulse">
                    Sessão em Curso
                  </span>
                </div>
              </div>

              <div className="space-y-6">
                {/* Notas de Evolução */}
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase mb-2">Observações e Evolução Clínica</label>
                  <textarea
                    required
                    rows={8}
                    className="w-full p-4 border border-slate-200 rounded-2xl bg-slate-50 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all text-sm leading-relaxed"
                    placeholder="Descreva detalhadamente o progresso do paciente nesta sessão..."
                    value={evolutionNotes}
                    onChange={e => setEvolutionNotes(e.target.value)}
                  />
                </div>

                {/* Seção de Exames */}
                <div className="pt-6 border-t border-slate-100">
                  <h4 className="text-xs font-bold text-slate-400 uppercase mb-4 flex items-center gap-2">
                    <Activity size={16} /> Registro de Exames (Opcional)
                  </h4>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <div className="flex items-center gap-2 text-indigo-600 mb-1">
                        <Ear size={14} />
                        <span className="text-[10px] font-bold uppercase">Teste da Orelhinha</span>
                      </div>
                      <input 
                        className="w-full p-2 text-xs border border-slate-200 rounded-lg bg-slate-50"
                        placeholder="Resultado..."
                        value={examDetails.testeOrelhinha}
                        onChange={e => setExamDetails({...examDetails, testeOrelhinha: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <div className="flex items-center gap-2 text-rose-600 mb-1">
                        <Baby size={14} />
                        <span className="text-[10px] font-bold uppercase">Teste da Linguinha</span>
                      </div>
                      <input 
                        className="w-full p-2 text-xs border border-slate-200 rounded-lg bg-slate-50"
                        placeholder="Resultado..."
                        value={examDetails.testeLinguinha}
                        onChange={e => setExamDetails({...examDetails, testeLinguinha: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <div className="flex items-center gap-2 text-blue-600 mb-1">
                        <Stethoscope size={14} />
                        <span className="text-[10px] font-bold uppercase">Audiometria</span>
                      </div>
                      <input 
                        className="w-full p-2 text-xs border border-slate-200 rounded-lg bg-slate-50"
                        placeholder="Tonal/Vocal..."
                        value={examDetails.audiometria}
                        onChange={e => setExamDetails({...examDetails, audiometria: e.target.value})}
                      />
                    </div>
                  </div>
                </div>
              </div>

              <div className="mt-8 pt-8 border-t border-slate-100 flex justify-end">
                <button
                  type="submit"
                  className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200 transition-all flex items-center gap-2"
                >
                  <Save size={20} />
                  Finalizar Atendimento
                </button>
              </div>
            </div>
          </form>
        ) : (
          <div className="h-full min-h-[400px] bg-white rounded-2xl border-2 border-dashed border-slate-200 flex flex-col items-center justify-center p-8 text-center">
            <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4 text-slate-300">
              <ClipboardList size={40} />
            </div>
            <h3 className="text-lg font-bold text-slate-400">Nenhum atendimento iniciado</h3>
            <p className="text-sm text-slate-400 max-w-xs mx-auto">Selecione um paciente na lista ao lado para iniciar a sessão e registrar a evolução no prontuário.</p>
          </div>
        )}
      </div>
    </div>
  );
};

