                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1 text-[10px] font-bold uppercase">Tipo de Registro</label>
                  <select 
                    className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50"
                    value={recordType}
                    onChange={e => setRecordType(e.target.value as RecordType)}
