                        type="text" className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" 
                        value={evaluationData.profissao}
                        onChange={e => setEvaluationData({...evaluationData, profissao: e.target.value})}
                      />
                    </div>
                    <div>
                      <label className="block text-[10px] font-bold text-slate-400 mb-1">Qtd. Sessões Previstas</label>
                      <input 
                        type="number" className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" 
                        value={evaluationData.quantidadeSessao}
                        onChange={e => setEvaluationData({...evaluationData, quantidadeSessao: parseInt(e.target.value)})}
                      />
                    </div>
                    <div>
                      <label className="block text-[10px] font-bold text-slate-400 mb-1">Nome da Mãe</label>
                      <input 
                        type="text" className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" 
                        value={evaluationData.nomeMae}
                        onChange={e => setEvaluationData({...evaluationData, nomeMae: e.target.value})}
                      />
                    </div>
                    <div>
                      <label className="block text-[10px] font-bold text-slate-400 mb-1">Nome do Pai</label>
                      <input 
                        type="text" className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" 
                        value={evaluationData.nomePai}
                        onChange={e => setEvaluationData({...evaluationData, nomePai: e.target.value})}
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-400 mb-1">Queixa Principal</label>
                    <textarea 
                      className="w-full p-2.5 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 bg-slate-50" rows={2}
                      value={evaluationData.queixaPrincipal}
                      onChange={e => setEvaluationData({...evaluationData, queixaPrincipal: e.target.value})}
                    />
                  </div>
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1 text-[10px] font-bold uppercase">Notas Clínicas / Evolução</label>
                <textarea 
                  required
                  rows={4}
                  className="w-full p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm bg-slate-50"
                  placeholder="Descreva detalhadamente o atendimento..."
                  value={notes}
                  onChange={e => setNotes(e.target.value)}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1 text-[10px] font-bold uppercase">Observações Adicionais</label>
                <textarea 
                  rows={4}
                  className="w-full p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm bg-slate-50"
                  placeholder="Insira notas adicionais sobre o atendimento, histórico complementar ou detalhes logísticos..."
                  value={observacoesAdicionais}
                  onChange={e => setObservacoesAdicionais(e.target.value)}
                />
              </div>

              <div className="flex gap-4 mt-8">
                <button 
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 px-4 py-3 border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 font-bold transition-all"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-100 font-bold transition-all"
                >
                  Salvar no Prontuário
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Records;

import React, { useState, useEffect } from 'react';
import { useApp } from '../store/AppContext';
import { RecordType, AppointmentStatus, MedicalRecord, Patient } from '../types';
import { 
  Activity, 
  User, 
  ClipboardList, 
  Save, 
  Stethoscope, 
  Ear, 
  Baby, 
  CheckCircle2,
  Clock,
  History,
  FileText,
  Briefcase,
  FileDown,
  Mail,
  Loader2,
  Check
} from 'lucide-react';
import { formatDate } from '../utils/helpers';
import { jsPDF } from 'jspdf';

const Clinic: React.FC = () => {
  const { appointments, patients, records, triages, addMedicalRecord, updateMedicalRecord } = useApp();
  const [selectedAppId, setSelectedAppId] = useState<string>('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');

  // Estado unificado para o Prontuário Único
  const [formData, setFormData] = useState({
    profissao: '',
    nomeMae: '',
    nomePai: '',
    queixaPrincipal: '',
    exameSolicitado: '',
    quantidadeSessao: 1,
    notes: '',
    testeOrelhinha: '',
    testeLinguinha: '',
    audiometria: '',
    dataInicio: '',
    dataFim: ''
  });

  const today = new Date().toISOString().split('T')[0];
  const todayApps = appointments.filter(a => a.date === today && a.status === AppointmentStatus.CONFIRMADO);

  const activeApp = appointments.find(a => a.id === selectedAppId);
  const activePatient = patients.find(p => p.id === activeApp?.patientId);
  const activeTriage = triages.find(t => t.appointmentId === selectedAppId);

  // Busca o registro único existente para este agendamento
  const existingRecord = records.find(r => r.appointmentId === selectedAppId);

  // Efeito para carregar dados quando mudar o paciente selecionado
  useEffect(() => {
    if (existingRecord) {
      setFormData({
        profissao: existingRecord.details.profissao || '',
        nomeMae: existingRecord.details.nomeMae || '',
        nomePai: existingRecord.details.nomePai || '',
        queixaPrincipal: existingRecord.details.queixaPrincipal || '',
        exameSolicitado: existingRecord.details.exameSolicitado || '',
        quantidadeSessao: existingRecord.details.quantidadeSessao || 1,
        notes: existingRecord.details.notes || '',
        testeOrelhinha: existingRecord.details.exams?.testeOrelhinha || '',
        testeLinguinha: existingRecord.details.exams?.testeLinguinha || '',
        audiometria: existingRecord.details.exams?.audiometria || '',
        dataInicio: existingRecord.details.dataInicio || new Date().toISOString(),
        dataFim: existingRecord.details.dataFim || ''
      });
    } else {
      // Reset para novo registro se não existir
      setFormData({
        profissao: '', nomeMae: '', nomePai: '', queixaPrincipal: '', exameSolicitado: '',
        quantidadeSessao: 1, notes: '', testeOrelhinha: '', testeLinguinha: '',
        audiometria: '', dataInicio: new Date().toISOString(), dataFim: ''
      });
    }
    setSaveStatus('idle');
  }, [selectedAppId, existingRecord]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedAppId) return;

    setSaveStatus('saving');

    const recordPayload = {
      appointmentId: selectedAppId,
      type: RecordType.CONSULTA_AVALIACAO, // Tipo principal unificado
      details: {
        ...formData,
        exams: {
          testeOrelhinha: formData.testeOrelhinha,
          testeLinguinha: formData.testeLinguinha,
          audiometria: formData.audiometria
        },
        dataUltimaModificacao: new Date().toISOString()
      }
    };

    // Simulação de delay de rede
    setTimeout(() => {
      if (existingRecord) {
        updateMedicalRecord(existingRecord.id, recordPayload);
      } else {
        addMedicalRecord(recordPayload);
      }
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 3000);
    }, 800);
  };

  const generatePDF = () => {
    if (!activePatient) return;
    const doc = new jsPDF();
    doc.setFontSize(20);
    doc.setTextColor(79, 70, 229);
    doc.text('Relatório de Atendimento Unificado', 20, 20);

    doc.setFontSize(10);
    doc.setTextColor(100);
    doc.text(`Paciente: ${activePatient.fullName}`, 20, 30);
    doc.text(`Data: ${formatDate(today)}`, 20, 35);

    doc.setFontSize(12);
    doc.setTextColor(0);
    doc.setFont('helvetica', 'bold');
    doc.text('1. DADOS DE AVALIAÇÃO', 20, 50);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    doc.text(`Profissão: ${formData.profissao}`, 20, 60);
    doc.text(`Queixa: ${formData.queixaPrincipal}`, 20, 65);

    doc.setFont('helvetica', 'bold');
    doc.text('2. EVOLUÇÃO CLÍNICA', 20, 80);
    doc.setFont('helvetica', 'normal');
    const notesLines = doc.splitTextToSize(formData.notes, 170);
    doc.text(notesLines, 20, 90);

    doc.save(`atendimento_${activePatient.fullName.replace(/\s+/g, '_')}.pdf`);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
      {/* Sidebar de Pacientes */}
      <div className="lg:col-span-3 space-y-6">
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2 text-sm uppercase tracking-wider">
            <Clock size={16} className="text-indigo-600" />
            Agenda do Dia
          </h3>
          <div className="space-y-2">
            {todayApps.length > 0 ? todayApps.map(app => {
              const p = patients.find(pat => pat.id === app.patientId);
              const hasRec = records.some(r => r.appointmentId === app.id);
              return (
                <button
                  key={app.id}
                  onClick={() => setSelectedAppId(app.id)}
                  className={`w-full p-3 rounded-xl border-2 transition-all text-left group ${
                    selectedAppId === app.id 
                    ? 'border-indigo-600 bg-indigo-50 shadow-md' 
                    : 'border-slate-50 bg-slate-50 hover:border-indigo-200'
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="font-bold text-slate-800 text-xs">{p?.fullName}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{app.time}</p>
                    </div>
                    {hasRec && <FileText size={12} className="text-indigo-400" />}
                  </div>
                </button>
              );
            }) : (
              <p className="text-[10px] text-slate-400 italic text-center py-4">Nenhum atendimento confirmado.</p>
            )}
          </div>
        </div>

        {activePatient && (
          <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 animate-in slide-in-from-left-4">
             <div className="flex items-center gap-3 mb-4">
               <div className="w-10 h-10 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center font-bold">
                 {activePatient.fullName[0]}
               </div>
               <div>
                 <p className="text-sm font-bold text-slate-800">{activePatient.fullName}</p>
                 <p className="text-[10px] text-slate-400 font-bold uppercase">{activePatient.age} anos</p>
               </div>
             </div>

             <div className="space-y-3 pt-3 border-t border-slate-50">
                <div className="flex items-center justify-between text-[10px]">
                  <span className="text-slate-400 font-bold uppercase">Status Triagem</span>
                  <span className={`font-bold ${activeTriage ? 'text-emerald-500' : 'text-slate-300'}`}>
                    {activeTriage ? activeTriage.status : 'Pendente'}
                  </span>
                </div>
                <button 
                  onClick={generatePDF}
                  className="w-full py-2 bg-slate-50 text-slate-600 rounded-lg text-[10px] font-bold hover:bg-indigo-50 hover:text-indigo-600 transition-all flex items-center justify-center gap-2"
                >
                  <FileDown size={14} /> Exportar Atendimento
                </button>
             </div>
          </div>
        )}
      </div>

      {/* Área Principal - Prontuário Único */}
      <div className="lg:col-span-9">
        {selectedAppId ? (
          <form onSubmit={handleSave} className="space-y-6 animate-in fade-in zoom-in-95 duration-300 pb-20">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
              <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <div>
                  <h2 className="text-2xl font-bold text-slate-800">Prontuário de Atendimento</h2>
                  <p className="text-xs text-slate-400 mt-1">Todas as informações deste atendimento serão salvas em um registro único.</p>
                </div>
                <div className="flex items-center gap-3">
                   {saveStatus === 'saving' && <span className="text-[10px] font-bold text-indigo-500 flex items-center gap-1"><Loader2 size={12} className="animate-spin" /> Salvando...</span>}
                   {saveStatus === 'saved' && <span className="text-[10px] font-bold text-emerald-500 flex items-center gap-1"><Check size={12} /> Sincronizado</span>}
                </div>
              </div>

              <div className="space-y-10">
                {/* Seção 1: Avaliação e Dados Gerais */}
                <section>
                  <h3 className="text-xs font-black text-slate-300 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                    <User size={16} /> Fase 4: Consulta e Avaliação
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-[10px] font-bold text-slate-400 uppercase mb-2">Profissão</label>
                      <div className="relative">
                        <Briefcase className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                        <input 
                          type="text" className="w-full pl-10 p-3 bg-slate-50 border border-slate-100 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                          value={formData.profissao}
                          onChange={e => setFormData({...formData, profissao: e.target.value})}
                          placeholder="Ex: Professor"
                        />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-2">Nome da Mãe</label>
                        <input 
                          type="text" className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                          value={formData.nomeMae}
                          onChange={e => setFormData({...formData, nomeMae: e.target.value})}
                        />
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-2">Nome do Pai</label>
                        <input 
                          type="text" className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                          value={formData.nomePai}
                          onChange={e => setFormData({...formData, nomePai: e.target.value})}
                        />
                      </div>
                    </div>
                  </div>
                  <div className="mt-6">
                    <label className="block text-[10px] font-bold text-slate-400 uppercase mb-2">Queixa Principal</label>
                    <textarea 
                      className="w-full p-4 bg-slate-50 border border-slate-100 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm italic"
                      rows={2}
                      value={formData.queixaPrincipal}
                      onChange={e => setFormData({...formData, queixaPrincipal: e.target.value})}
                      placeholder="Relate o motivo da busca pelo atendimento..."
                    />
                  </div>
                </section>

                {/* Seção 2: Evolução da Sessão */}
                <section>
                  <h3 className="text-xs font-black text-slate-300 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                    <ClipboardList size={16} /> Fase 4: Evolução do Atendimento
                  </h3>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-400 uppercase mb-2">Notas Clínicas e Evolução</label>
                    <textarea 
                      required
                      className="w-full p-5 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 text-sm leading-relaxed"
                      rows={8}
                      value={formData.notes}
                      onChange={e => setFormData({...formData, notes: e.target.value})}
                      placeholder="Descreva detalhadamente o que foi trabalhado na sessão e a resposta do paciente..."
                    />
                  </div>
                </section>

                {/* Seção 3: Exames e Testes */}
                <section className="p-6 bg-slate-50/50 rounded-3xl border border-slate-100">
                  <h3 className="text-xs font-black text-slate-300 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                    <Activity size={16} /> Fase 5: Exames e Procedimentos
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
                      <div className="flex items-center gap-2 text-indigo-600 mb-3">
                        <Ear size={14} />
                        <span className="text-[10px] font-bold uppercase tracking-wider">Teste da Orelhinha</span>
                      </div>
                      <input 
                        className="w-full p-2 text-xs border border-slate-100 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
                        placeholder="Resultado..."
                        value={formData.testeOrelhinha}
                        onChange={e => setFormData({...formData, testeOrelhinha: e.target.value})}
                      />
                    </div>
                    <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
                      <div className="flex items-center gap-2 text-rose-600 mb-3">
                        <Baby size={14} />
