                      <div className="flex items-center gap-2 text-blue-600 mb-3">
                        <Stethoscope size={14} />
                        <span className="text-[10px] font-bold uppercase tracking-wider">Audiometria</span>
                      </div>
                      <input 
                        className="w-full p-2 text-xs border border-slate-100 rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
                        placeholder="Tonal/Vocal..."
                        value={formData.audiometria}
